-- =============================================================================
--  Initial schema for this launch
--
--  Generated by `pnpm init:launch`. Every occurrence of the schema name below
--  is rewritten to launch_<slug> for your launch.
--
--  Apply with:  pnpm db:push
--
--  ⚠️  AFTER APPLYING, one manual step is required:
--      Supabase Dashboard → Settings → API → Exposed schemas → add this schema.
--      Until you do, PostgREST returns 404 for every table here and the error
--      message does not mention the real cause. This is the single most common
--      way to lose an hour with a schema-per-tenant setup.
-- =============================================================================

create schema if not exists launch_launch_template;

-- citext gives us case-insensitive email uniqueness without lower() everywhere.
-- Supabase convention is to install extensions into the `extensions` schema.
create extension if not exists citext with schema extensions;


-- ─── leads ───────────────────────────────────────────────────────────────────
create table if not exists launch_launch_template.leads (
  id                  uuid primary key default gen_random_uuid(),
  email               extensions.citext not null unique,
  name                text,
  source              text,
  utm                 jsonb,
  posthog_distinct_id text,
  -- SHA-256 of (site_url + client IP). Stored rather than the address itself:
  -- rate limiting only needs equality, and this keeps raw PII out of the table.
  ip_hash             text,
  created_at          timestamptz not null default now()
);

create index if not exists leads_created_at_idx on launch_launch_template.leads (created_at desc);
create index if not exists leads_ip_hash_created_idx on launch_launch_template.leads (ip_hash, created_at desc);


-- ─── customers ───────────────────────────────────────────────────────────────
create table if not exists launch_launch_template.customers (
  id                 uuid primary key default gen_random_uuid(),
  email              extensions.citext not null unique,
  stripe_customer_id text unique,
  created_at         timestamptz not null default now()
);


-- ─── orders ──────────────────────────────────────────────────────────────────
create table if not exists launch_launch_template.orders (
  id                       uuid primary key default gen_random_uuid(),
  customer_id              uuid references launch_launch_template.customers (id) on delete set null,
  stripe_session_id        text not null unique,
  stripe_payment_intent_id text,
  amount_cents             integer not null check (amount_cents >= 0),
  currency                 text not null default 'usd',
  status                   text not null default 'pending',
  created_at               timestamptz not null default now()
);

create index if not exists orders_customer_idx on launch_launch_template.orders (customer_id);
create index if not exists orders_payment_intent_idx on launch_launch_template.orders (stripe_payment_intent_id);


-- ─── bookings ────────────────────────────────────────────────────────────────
create table if not exists launch_launch_template.bookings (
  id              uuid primary key default gen_random_uuid(),
  cal_booking_uid text not null unique,
  email           extensions.citext,
  event_type      text,
  start_time      timestamptz,
  end_time        timestamptz,
  status          text not null default 'confirmed',
  created_at      timestamptz not null default now()
);

create index if not exists bookings_start_time_idx on launch_launch_template.bookings (start_time desc);


-- ─── webhook_events — THE IDEMPOTENCY LEDGER ─────────────────────────────────
-- Every webhook claims its row here before running any business logic. The
-- unique constraint is what makes a retried delivery a no-op instead of a
-- duplicated order.
--
-- Keyed on (provider, external_id) rather than external_id alone: an id is only
-- unique within the provider that issued it, and two providers could in
-- principle mint the same string. Still exactly-once per provider.
create table if not exists launch_launch_template.webhook_events (
  id           uuid primary key default gen_random_uuid(),
  provider     text not null,
  external_id  text not null,
  payload      jsonb not null,
  processed_at timestamptz,
  error        text,
  created_at   timestamptz not null default now(),
  constraint webhook_events_provider_external_id_key unique (provider, external_id)
);

-- Finds events that need a manual replay.
create index if not exists webhook_events_unprocessed_idx
  on launch_launch_template.webhook_events (provider, created_at desc)
  where processed_at is null;


-- =============================================================================
--  ROW LEVEL SECURITY — deny by default, everywhere.
--
--  RLS is enabled on all five tables and NO policy grants anon or authenticated
--  any access. That is deliberate, not an oversight: the service-role key used
--  by webhook handlers bypasses RLS entirely, so webhooks keep working, while a
--  leaked anon key yields exactly nothing.
--
--  Lead capture — the one thing the public genuinely must do — goes through the
--  SECURITY DEFINER function at the bottom of this file instead of a policy.
-- =============================================================================

alter table launch_launch_template.leads          enable row level security;
alter table launch_launch_template.customers      enable row level security;
alter table launch_launch_template.orders         enable row level security;
alter table launch_launch_template.bookings       enable row level security;
alter table launch_launch_template.webhook_events enable row level security;

-- Force RLS for table owners too, so a mistakenly-owner-scoped connection
-- cannot quietly read everything.
alter table launch_launch_template.leads          force row level security;
alter table launch_launch_template.customers      force row level security;
alter table launch_launch_template.orders         force row level security;
alter table launch_launch_template.bookings       force row level security;
alter table launch_launch_template.webhook_events force row level security;

-- Explicit deny-all policies. Postgres already denies when a table has RLS on
-- and no matching policy; these exist so that `\d+` and the Supabase policy
-- editor state the intent out loud rather than showing a blank list that reads
-- like someone forgot.
do $$
declare
  t text;
begin
  foreach t in array array['leads', 'customers', 'orders', 'bookings', 'webhook_events']
  loop
    execute format(
      'drop policy if exists %I on launch_launch_template.%I',
      'deny_all_' || t, t
    );
    execute format(
      'create policy %I on launch_launch_template.%I as restrictive for all to anon, authenticated using (false) with check (false)',
      'deny_all_' || t, t
    );
  end loop;
end
$$;


-- =============================================================================
--  GRANTS
--
--  PostgREST cannot see this schema at all without USAGE, and the dashboard
--  step above is the other half of that. anon gets USAGE on the schema and
--  EXECUTE on exactly one function — and no table privileges whatsoever.
-- =============================================================================

grant usage on schema launch_launch_template to anon, authenticated, service_role;

-- service_role does the real work; RLS does not apply to it.
grant all on all tables in schema launch_launch_template to service_role;
grant all on all sequences in schema launch_launch_template to service_role;
grant all on all routines in schema launch_launch_template to service_role;

alter default privileges in schema launch_launch_template
  grant all on tables to service_role;
alter default privileges in schema launch_launch_template
  grant all on sequences to service_role;

-- Deliberately NOT granted to anon/authenticated:
--   grant select/insert/update/delete on any table.


-- =============================================================================
--  capture_lead — the only public write path.
--
--  SECURITY DEFINER so it runs as the owner and can insert into `leads` despite
--  anon having no table grant. The rate limit lives inside the function, where
--  a caller cannot skip it.
--
--  `search_path` is pinned: without it, a caller able to set their own
--  search_path could shadow `leads` with their own table and hijack a
--  definer-rights function. This is the standard SECURITY DEFINER hardening.
-- =============================================================================

create or replace function launch_launch_template.capture_lead(
  p_email               text,
  p_name                text default null,
  p_source              text default null,
  p_utm                 jsonb default null,
  p_posthog_distinct_id text default null,
  p_ip_hash             text default null
)
returns uuid
language plpgsql
security definer
set search_path = launch_launch_template, extensions, pg_temp
as $$
declare
  v_recent  integer;
  v_id      uuid;
  c_window  constant interval := interval '1 hour';
  c_max     constant integer  := 5;
begin
  if p_email is null or p_email !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' then
    raise exception 'invalid_email';
  end if;

  -- Rate limit per hashed IP. Unknown/absent hashes are limited as one bucket,
  -- which is the conservative choice.
  if p_ip_hash is not null then
    select count(*) into v_recent
    from launch_launch_template.leads
    where ip_hash = p_ip_hash
      and created_at > now() - c_window;

    if v_recent >= c_max then
      raise exception 'rate_limit_exceeded';
    end if;
  end if;

  insert into launch_launch_template.leads
    (email, name, source, utm, posthog_distinct_id, ip_hash)
  values
    (p_email::extensions.citext, p_name, p_source, p_utm, p_posthog_distinct_id, p_ip_hash)
  on conflict (email) do update
    set name                = coalesce(excluded.name, launch_launch_template.leads.name),
        source              = coalesce(excluded.source, launch_launch_template.leads.source),
        utm                 = coalesce(excluded.utm, launch_launch_template.leads.utm),
        posthog_distinct_id = coalesce(
                                excluded.posthog_distinct_id,
                                launch_launch_template.leads.posthog_distinct_id
                              )
  returning id into v_id;

  return v_id;
end;
$$;

-- Lock down who may call it, then hand it to the public roles explicitly.
revoke all on function launch_launch_template.capture_lead(text, text, text, jsonb, text, text) from public;
grant execute on function launch_launch_template.capture_lead(text, text, text, jsonb, text, text)
  to anon, authenticated, service_role;
